export default async (ctx, client) => {
  const orgs = await client.organizations.list?.().catch((e) => String(e));
  return { ctx, orgs };
}

export default async (ctx, client) => {
  const convs = await client.conversations.list({ limit: 25 }).catch((e) => String(e));
  const notifs = await client.notifications.list({ limit: 25 }).catch((e) => String(e));
  return { convs, notifs };
}

export default async (ctx, client) => {
  const agents = await client.agents.list().catch((e) => String(e));
  const out = { agents, conversations: {} };
  if (Array.isArray(agents)) {
    for (const a of agents.slice(0, 10)) {
      out.conversations[a.slug ?? a.id] = await client.conversations
        .list({ agent_id: a.id, limit: 10 })
        .catch((e) => String(e));
    }
  }
  return out;
}

export default async (ctx, client) => {
  const res = await client.agents.list();
  const out = {};
  for (const a of res.agents) {
    out[a.id] = await client.conversations.list({ agent_id: a.id, limit: 8 }).catch((e) => String(e));
  }
  return out;
}

export default async (ctx, client) => {
  const res = await client.agents.list();
  const out = {};
  for (const a of res.agents) {
    const r = await client.conversations.list({ agent_id: a.id }).catch((e) => String(e));
    out[a.id] = Array.isArray(r?.conversations)
      ? { count: r.conversations.length, recent: r.conversations.slice(0, 8) }
      : r;
  }
  return out;
}

export default async (ctx, client) => {
  const failing = await client.feeds.list({ health: 'failing', limit: 100 }).catch((e) => String(e));
  const runs = await client.operations
    .listRuns({ limit: 100, created_after: '2026-08-04T00:00:00Z' })
    .catch((e) => String(e));
  const behaviors = await client.behaviors.list().catch((e) => String(e));
  const summarize = (r) => {
    if (!Array.isArray(r?.runs)) return r;
    const by = {};
    for (const x of r.runs) {
      const k = `${x.run_type ?? '?'}|${x.status ?? '?'}`;
      by[k] = (by[k] ?? 0) + 1;
    }
    return { total: r.runs.length, by, failures: r.runs.filter((x) => x.status && !['success', 'completed', 'running', 'succeeded'].includes(x.status)).slice(0, 25) };
  };
  return {
    failingFeeds: Array.isArray(failing?.feeds)
      ? failing.feeds.map((f) => ({ id: f.id, key: f.feed_key, conn: f.connection_id, status: f.status, last: f.last_sync_at, err: f.last_error ?? f.error_message, fails: f.consecutive_failures }))
      : failing,
    feedsTotal: failing?.total,
    runs: summarize(runs),
    behaviors: Array.isArray(behaviors?.behaviors)
      ? behaviors.behaviors.map((b) => ({ id: b.id, name: b.name, status: b.status, enabled: b.enabled, trigger: b.trigger?.type ?? b.trigger_type, last_run_at: b.last_run_at }))
      : behaviors,
  };
}

