export default async (ctx, client) => {
  const out = {};
  for (const id of [479, 432]) {
    const r = await client.operations.listAvailable({ connection_id: id }).catch((e) => String(e));
    out[id] = typeof r === 'string' ? r : { readiness: r.readiness, targets: r.execution_targets };
  }
  return out;
}

export default async (ctx, client) => {
  const r = await client.operations.listAvailable({ connection_id: 479 });
  return JSON.parse(JSON.stringify(r)).operations ? Object.keys(r) : r;
}

export default async (ctx, client) => {
  const out = {};
  for (const id of [479, 432]) {
    const r = await client.operations.listAvailable({ connection_id: id });
    const nav = r.operations.find((o) => o.operation_key === 'navigate') ?? r.operations[0];
    out[id] = { total: r.total, sample: nav };
  }
  return out;
}

export default async (ctx, client) => {
  const CHROME = 479;
  const nav = await client.operations.execute({
    connection_id: CHROME,
    operation_key: 'navigate',
    input: { url: 'https://app.lobu.ai/buremba', open_in_new_tab: true, wait_for_load: true },
  });
  const tab = nav.output?.tab_id;
  const probe = await client.operations.execute({
    connection_id: CHROME,
    operation_key: 'evaluate',
    input: {
      tab_id: tab,
      await_promise: true,
      expression: `(async () => {
        await new Promise(r => setTimeout(r, 4000));
        const links = Array.from(document.querySelectorAll('a[href]')).map(a => ({ t: (a.innerText||'').trim().slice(0,80), h: a.getAttribute('href') })).filter(x => x.t || x.h);
        return JSON.stringify({
          url: location.href,
          title: document.title,
          text: document.body.innerText.slice(0, 2500),
          links: links.slice(0, 120),
        });
      })()`,
    },
  });
  return { tab, status: probe.status, out: probe.output };
