export default async (ctx, client) => {
  const CHROME = 479;
  const TAB = 558577453;
  const ev = (expression) =>
    client.operations.execute({
      connection_id: CHROME,
      operation_key: 'evaluate',
      input: { tab_id: TAB, await_promise: true, expression },
    });

  const header = await ev(`(async () => {
    const btns = Array.from(document.querySelectorAll('button')).map((b, i) => ({
      i, t: (b.innerText||'').trim().slice(0,40), a: b.getAttribute('aria-label'), d: b.getAttribute('data-testid'),
    }));
    return JSON.stringify({ buttons: btns.slice(0, 60) });
  })()`);

  const nav = await client.operations.execute({
    connection_id: CHROME,
    operation_key: 'navigate',
    input: { tab_id: TAB, url: 'https://app.lobu.ai/buremba/memory?run_ids=871539', wait_for_load: true },
  });

  const approval = await ev(`(async () => {
    await new Promise(r => setTimeout(r, 5000));
    const btns = Array.from(document.querySelectorAll('button')).map(b => (b.innerText||'').trim()).filter(Boolean);
    return JSON.stringify({ url: location.href, text: document.body.innerText.slice(0, 3000), buttons: btns.slice(0, 40) });
  })()`);

  return { header: header.output?.value, navStatus: nav.status, approval: approval.output?.value };
}

