export default async (ctx, client) => {
  const { behaviors } = await client.behaviors.list();
  const out = [];
  for (const b of behaviors) {
    const r = await client.operations.listRuns({ behavior_ids: [b.id], limit: 3 }).catch((e) => String(e));
    out.push({
      id: b.id,
      name: b.name,
      status: b.status,
      lastRuns: Array.isArray(r?.runs) ? r.runs.map((x) => ({ id: x.id, status: x.status, created_at: x.created_at, err: x.error_message })) : r,
    });
  }
  return out;
}

export default async (ctx, client) => {
  const out = {};
  for (const id of [5, 20, 70, 71]) {
