}

export default async (ctx, client) => {
  const CHROME = 479;
  const TAB = 558577453;
  const go = (url) => client.operations.execute({ connection_id: CHROME, operation_key: 'navigate', input: { tab_id: TAB, url, wait_for_load: true } });
  const ev = (expression) => client.operations.execute({ connection_id: CHROME, operation_key: 'evaluate', input: { tab_id: TAB, await_promise: true, expression } });

  await go('https://app.lobu.ai/buremba/behaviors');
  const cards = await ev(`(async () => {
    await new Promise(r => setTimeout(r, 5000));
    const main = document.querySelector('main') || document.body;
