  })()`);

  await go('https://app.lobu.ai/buremba/activity');
  const attention = await ev(`(async () => {
    await new Promise(r => setTimeout(r, 4000));
    const tab = Array.from(document.querySelectorAll('button, [role="tab"], a')).find(e => (e.innerText||'').trim().startsWith('Needs attention'));
