export default async (ctx, client) => {
  const r = await client.operations.listRuns({ status: 'pending_approval', limit: 50 }).catch((e) => String(e));
  if (typeof r === 'string') {
    const all = await client.operations.listRuns({ limit: 200 });
    const p = all.runs.filter((x) => x.approval_status && x.approval_status !== 'auto');
    return { hint: r, byApproval: p.map((x) => ({ id: x.id, op: x.operation_key, conn: x.connection_display_name, approval: x.approval_status, status: x.status, at: x.created_at })) };
  }
  return r.runs.map((x) => ({ id: x.id, op: x.operation_key, conn: x.connection_display_name, approval: x.approval_status, status: x.status, at: x.created_at }));
}

export default async (ctx, client) => {
  let cursor, all = [], pages = 0;
  while (pages < 6) {
    const r = await client.notifications.list(cursor ? { cursor } : {});
    all = all.concat(r.notifications);
    if (!r.nextCursor) break;
    cursor = r.nextCursor;
    pages++;
  }
  const approvals = all.filter((n) => n.type === 'action_approval_needed');
  return {
    scanned: all.length,
    approvals: approvals.map((n) => ({ id: n.id, title: n.title, run: n.approval_run_id, status: n.approval_status, key: n.approval_action_key, at: n.created_at })),
  };
}

export default async (ctx, client) => {
  const ids = [871539, 852719, 852658, 852657, 846979, 841965, 838309, 838072, 836326, 835862, 834776, 829076];
  const r = await client.operations.listRuns({ limit: 500, created_after: '2026-07-31T00:00:00Z' });
  const byId = new Map(r.runs.map((x) => [x.id, x]));
  return ids.map((id) => {
    const x = byId.get(id);
    return x
      ? { id, op: x.operation_key, run_status: x.status, approval: x.approval_status, at: x.created_at, err: (x.error_message ?? '').slice(0, 120) }
      : { id, missing: true };
  });
}

export default async (ctx, client) => {
  const want = new Set([852719, 852658, 852657, 846979, 841965, 838309, 838072, 829076]);
  const found = [];
  for (const w of [
    ['2026-08-04T21:00:00Z', '2026-08-04T22:00:00Z'],
    ['2026-08-04T04:00:00Z', '2026-08-04T05:00:00Z'],
    ['2026-08-03T15:00:00Z', '2026-08-03T16:00:00Z'],
    ['2026-08-03T05:00:00Z', '2026-08-03T06:00:00Z'],
    ['2026-08-02T01:00:00Z', '2026-08-02T02:00:00Z'],
  ]) {
    const r = await client.operations.listRuns({ limit: 100, created_after: w[0], created_before: w[1] });
    for (const x of r.runs) if (want.has(x.id)) found.push({ id: x.id, op: x.operation_key, status: x.status, approval: x.approval_status, err: (x.error_message ?? '').slice(0, 100) });
  }
  return found;
}

