export default async (ctx, client) => {
  const OLD = "lower(coalesce(metadata->>'author_handle','')) = 'buremba'";
  const NEW = "lower(coalesce(metadata->>'author_handle','')) = 'bu7emba'";

  const rows = await client.query(
    `SELECT sources, prompt, name, description FROM behaviors b
     JOIN behavior_versions v ON v.id = b.current_version_id
     WHERE b.id = 70`,
  );
  const row = rows[0];
  const sources = row.sources;
  const authored = sources.find((s) => s.name === 'authored_recent');
  if (!authored || !authored.query.includes(OLD)) {
    return { aborted: 'old pattern not present', found: authored?.query?.slice(0, 200) };
  }
  const patched = sources.map((s) =>
    s.name === 'authored_recent' ? { ...s, query: s.query.replace(OLD, NEW) } : s,
  );
  return {
    preview: patched.find((s) => s.name === 'authored_recent').query,
    otherSources: patched.filter((s) => s.name !== 'authored_recent').map((s) => s.name),
  };
}

export default async (ctx, client) => {
  const OLD = "lower(coalesce(metadata->>'author_handle','')) = 'buremba'";
  const NEW = "lower(coalesce(metadata->>'author_handle','')) = 'bu7emba'";

  const rows = await client.query(
    `SELECT b.sources AS sources, v.prompt AS prompt, v.name AS vname, v.description AS vdesc, v.outputs AS outputs
     FROM behaviors b JOIN behavior_versions v ON v.id = b.current_version_id WHERE b.id = 70`,
  );
  const row = rows[0];
  const sources = row.sources;
  const authored = sources.find((s) => s.name === 'authored_recent');
  if (!authored?.query?.includes(OLD)) return { aborted: 'old pattern absent', got: authored?.query?.slice(0, 160) };

  const patched = sources.map((s) =>
    s.name === 'authored_recent' ? { ...s, query: s.query.replace(OLD, NEW) } : s,
  );

  const created = await client.behaviors.createVersion({
    behavior_id: 70,
    name: row.vname,
    description: row.vdesc,
    prompt: row.prompt,
    sources: patched,
    outputs: row.outputs,
  });
  return { created, newAuthored: patched.find((s) => s.name === 'authored_recent').query };
}

export default async (ctx, client) => {
  const t = await client.behaviors.trigger({ behavior_id: 70 });
  return t;
}

export default async (ctx, client) => {
  for (let i = 0; i < 10; i++) {
    const r = await client.operations.getRun({ run_id: 872975 });
    if (r?.run?.status && !['pending', 'claimed', 'running'].includes(r.run.status)) {
      return { status: r.run.status, err: r.run.error_message, completed_at: r.run.completed_at };
    }
    await ctx.sleep(15000);
  }
  const r = await client.operations.getRun({ run_id: 872975 });
  return { stillRunning: true, status: r?.run?.status };
}

export default async (ctx, client) => {
  const r = await client.operations.getRun({ run_id: 872975 });
  const run = r.run ?? r;
  return {
    status: run.status,
    items_collected: run.items_collected,
    error: run.error_message,
    output: typeof run.output === 'object' ? JSON.stringify(run.output).slice(0, 2000) : run.output,
    checkpoint: run.checkpoint,
  };
}

