export default async (ctx, client) => {
  const rows = await client.query(
    `SELECT v.id, v.version, v.created_at,
            (SELECT string_agg(s->>'name', ',') FROM jsonb_array_elements(w.sources) s) AS src_names,
            (SELECT count(*) FROM jsonb_array_elements(w.sources) s WHERE s->>'query' LIKE '%bu7emba%') AS bu7,
            (SELECT count(*) FROM jsonb_array_elements(w.sources) s WHERE s->>'query' LIKE '%= ''buremba''%') AS bur
     FROM behavior_versions v
     LEFT JOIN watchers w ON w.current_version_id = v.id
     WHERE v.watcher_id = 70 ORDER BY v.version`,
  );
  return rows;
}

export default async (ctx, client) => {
  const rows = await client.query(
    `SELECT d.id, d.platform, d.label, d.last_seen_at, d.status,
            (now() - d.last_seen_at) AS age,
            (SELECT count(*) FROM connections c WHERE c.device_worker_id = d.id AND c.deleted_at IS NULL) AS conns
     FROM device_workers d
     WHERE d.organization_id = '${ctx.organization_id}'
     ORDER BY d.last_seen_at DESC NULLS LAST`,
  );
  return rows;
}

export default async (ctx, client) => {
  const r = await client.feeds.list({ limit: 200 });
  const feeds = (r.feeds ?? []).filter((f) => f.status === 'active');
  return feeds.map((f) => ({
    id: f.id, key: f.feed_key, conn: f.connection_id, sched: f.schedule ?? f.cron ?? null,
    last: f.last_sync_at, ok: f.last_sync_status, fails: f.consecutive_failures,
    err: (f.last_error ?? f.error_message ?? '').slice(0, 70),
  })).sort((a, b) => String(a.last).localeCompare(String(b.last)));
}

