        // "Nothing left to hand out" is not by itself proof that nothing is
        // running, so the decision is not taken here — pass what is live and
        // let StagedUpdateGate rule on it. `maxJobsPerPass` can also end the
        // drain with work still queued, which is safe (the relaunched app
        // re-polls) but is another reason not to read the loop's exit as
        // "idle". No-op unless an update is actually staged.
        OwlettoUpdater.shared.applyStagedUpdateIfIdle(
            activity: StagedUpdateGate.Activity(
                behaviorRunsInFlight: BehaviorDispatcher.shared.claimedRunCount,
                isRecordingAudio: isRecordingAudio
            )
        )
        // Header's "Connected · last poll Xs ago" already confirms
        // the cycle ran; per-job recap lives in `recentJobs` /
        // `recentRuns`. A "Synced N jobs" banner up here read like
        // a notification, so we suppress it. Errors still surface
        // via the catch arms below.
        setStatus("")
        lastSyncError = nil
        await refreshNotifications()
    } catch SyncDispatcher.CycleError.credentialsInvalid {
        // The CLI couldn't produce a token the server accepts (refresh
        // failed / session revoked). Drop in-memory creds + stop polling so
        // the connection card replaces the signed-in chrome instead of
        // looping 401s. The CLI session file is left as-is — the user can
        // re-auth with `lobu login` (Sign in), which heals it.
        Log.error(.sync, "credentials invalid, dropping back to connection card")
        stopAutoPoll()
        credentials = nil
        lastPollDate = nil
        lastPollSuccess = true
        lastSyncError = nil
        // The connection row now reads "Sign-in expired — reconnect" via
        // `sessionExpired`; clear the status banner so the same prompt
        // isn't shown twice (row + banner).
        sessionExpired = true
        setStatus("")
    } catch {
        lastPollDate = Date()
        lastPollSuccess = false
        // Stored on `lastSyncError`, surfaced inline only when the
        // user clicks "see details" — keeps the popover quiet by
        // default. The log keeps the raw text discoverable afterwards.
        lastSyncError = error.localizedDescription
        Log.error(.sync, "sync error: \(error.localizedDescription)")
        setStatus("")
    }
}

