content.content:
/// Run one poll cycle for `credentials` (the in-memory snapshot AppState
/// owns, already refreshed by `refreshCredentialsFromCLI` before syncNow).
/// On a 401 we re-fetch a live token via `refreshSession` — which delegates
/// to the CLI (`lobu whoami --json`, refreshing or re-minting via local-init)
/// — and retry once. A nil return, or a fresh token the server also rejects,
/// means the session is gone (`credentialsInvalid`).
static func runOneCycle(
    baseURL: String,
    capabilities: [String: Bool],
    credentials initial: OAuthCredentials,
    refreshSession: @escaping () async throws -> String?,
    // Fired once a job is actually claimed, so the UI can distinguish
    // "running something" from "polling". A poll happens every 10s under
    // computer use; keying an indicator off the poll would make it flicker
    // continuously and mean nothing.
    onJobClaimed: (@Sendable (String) -> Void)? = nil,
    // AppState's CACHED Full Disk Access flag, threaded through rather than
    // re-probed: os.shell uses it only to explain a timeout, and the probe
    // itself reads TCC-protected paths — the very thing that stalls.
    hasFullDiskAccess: Bool = false
) async throws -> CycleResult {
    var worker = WorkerClient(baseURL: initial.baseURL, accessToken: initial.accessToken)
    var effectiveToken = initial.accessToken
    let workerId = LobuWorkerIdentity.current()

    let job: WorkerJob?
    let raw: Data?
    do {
        (job, raw, _) = try await worker.pollRaw(workerId: workerId, capabilities: capabilities)
    } catch let WorkerClientError.http(_, status, _) where status == 401 {
        // Server says the token is dead. Ask the CLI for a fresh one and
        // retry once. A nil token (CLI can't refresh / session revoked) or
        // a second 401 means the user is locked out. Any other failure
        // (refreshSession throwing credentialsChanged, a transient network
        // blip on the retry poll) re-throws so a one-off hiccup doesn't sign
        // the user out.
        guard let freshToken = try await refreshSession(), !freshToken.isEmpty else {
            throw CycleError.credentialsInvalid
        }
        effectiveToken = freshToken
        worker = WorkerClient(baseURL: initial.baseURL, accessToken: freshToken)
        do {
            (job, raw, _) = try await worker.pollRaw(workerId: workerId, capabilities: capabilities)
        } catch let WorkerClientError.http(_, status, _) where status == 401 {
            // Fresh token is also rejected — server has revoked this worker.
            throw CycleError.credentialsInvalid
        }
    }
    guard let job else {
        return CycleResult(claimedJob: false, itemsStreamed: 0, connectorKey: nil, runId: nil)
    }
    // Behavior runs carry no connector_key, so fall through to the operation
    // and finally run_type rather than reporting an empty label.
    onJobClaimed?(job.operation_key ?? job.connector_key ?? job.run_type ?? "operation")

