export default async (ctx, client) => {
  const res = await client.notifications.list({ limit: 40 });
  const items = res.items ?? res.notifications ?? res ?? [];
  const summary = items.map((n) => ({
    id: n.id,
    title: (n.title ?? "").slice(0, 60),
    approval_status: n.approval_status ?? null,
    run_id: n.run_id ?? null,
    unread: n.unread ?? null,
  }));
  const byStatus = {};
  for (const s of summary) {
    const k = String(s.approval_status);
    byStatus[k] = (byStatus[k] ?? 0) + 1;
  }
  return { total: summary.length, byStatus, orphans: summary.filter((s) => s.approval_status === null || s.approval_status === "null").slice(0, 12) };
};

export default async (ctx, client) => {
  const res = await client.notifications.list({ limit: 60 });
  const items = res.items ?? res.notifications ?? [];
  const sample = items.find((n) => n.approval_status) ?? items[0];
  // Which notifications point at a proposal resource but have no resolved approval?
  const withResource = items.filter((n) => n.metadata?.resource_id || n.resource_id);
  return {
    fields: Object.keys(sample ?? {}),
    total: items.length,
    withResource: withResource.length,
    orphanCandidates: withResource
      .filter((n) => !n.approval_status)
      .map((n) => ({ id: n.id, title: (n.title ?? "").slice(0, 50), rid: n.metadata?.resource_id ?? n.resource_id }))
      .slice(0, 10),
  };
};

export default async (ctx, client) => {
  const res = await client.notifications.list({ limit: 60 });
  const items = res.items ?? res.notifications ?? [];
  return items
    .filter((n) => n.resource_id)
    .map((n) => ({
      id: n.id,
      title: (n.title ?? "").slice(0, 45),
      status: n.approval_status,
      run: n.approval_run_id,
      url: (n.resource_url ?? "").slice(0, 45),
      created: n.created_at,
    }));
};

