export default async (ctx, client) => {
  const res = await client.knowledge.read({
    behavior_id: "70",
    since: "2026-08-03",
    until: "2026-08-09",
  });
  return {
    keys: Object.keys(res ?? {}),
    window: res?.window ?? null,
    hasToken: Boolean(res?.window_token),
    tokenLen: res?.window_token ? String(res.window_token).length : 0,
    contentCount: Array.isArray(res?.content) ? res.content.length : null,
    sourceNames: res?.sources ? Object.keys(res.sources) : null,
  };
};

export default async (ctx, client) => {
  const res = await client.knowledge.read({
    behavior_id: "70",
    since: "2026-08-03",
    until: "2026-08-09",
  });
  const out = { window_start: res.window_start, window_end: res.window_end, lag: res.window_lag };
  out.sourceRowCounts = {};
  for (const [name, val] of Object.entries(res.sources ?? {})) {
    const rows = Array.isArray(val) ? val : (val?.rows ?? val?.data ?? []);
    out.sourceRowCounts[name] = Array.isArray(rows) ? rows.length : typeof val;
  }
  const ar = res.sources?.authored_recent;
  const arRows = Array.isArray(ar) ? ar : (ar?.rows ?? []);
  out.sampleHandles = arRows.slice(0, 3).map((r) => r.author_handle ?? r.handle ?? Object.keys(r).slice(0, 4));
  return out;
};

export default async (ctx, client) => {
  const r = await client.operations.execute({
    connection_id: 464,
    operation_key: "run",
    input: { command: "lobu whoami --json 2>&1 | head -c 400; echo; echo HOST=$(hostname); pgrep -lf 'Owletto.app/Contents/MacOS/Owletto' | head -2 || echo NO_OWLETTO" },
  });
  return r;
};

