      identities: [
        {
          namespace: X_IDENTITY.USER_ID,
          eventPath: "metadata.in_reply_to_user_id",
          primary: true,
        },
        {
          namespace: X_IDENTITY.HANDLE,
          eventPath: "metadata.in_reply_to_screen_name",
