import { describe, expect, test } from "bun:test";
import {
	SESSION_COOKIE_BASENAME,
	convergeResponseCookieScope,
	convergeSetCookieScope,
	countNamedCookies,
	hostOnlyExpiry,
	sessionCookieName,
