1	/**
2	 * Cookie-scope convergence for the Better Auth session cookie.
3	 *
4	 * The same cookie name can exist at two scopes at once — host-only
5	 * (`app.lobu.ai`) and domain-scoped (`Domain=.lobu.ai`). A browser sends BOTH
6	 * in one `Cookie` header, the server resolves the FIRST, and RFC 6265 §5.4
7	 * orders equal-path cookies oldest-first. A stale host-only session cookie is
8	 * therefore permanently unbeatable: every later sign-in writes a strictly
9	 * NEWER cookie that can never take precedence, so the user is locked out of
10	 * the app with no in-app way to recover. Measured on prod 2026-08-06 —
11	 * `dead; good` resolves to `null` while `good; dead` resolves to the session.
12	 *
13	 * Host-only twins are produced by any path that sets the session cookie
14	 * without the configured zone: the `/exchange-token` and `/local-init` deep
15	 * links used to, and `document.cookie` planting (see docs/BROWSER_TESTING.md)
16	 * still can.
17	 *
18	 * The cure is to make sign-in authoritative. Whenever a response sets a
19	 * domain-scoped auth cookie, it also expires the host-only twin of that same
20	 * name, so a single sign-in collapses the jar back to one cookie — which also
21	 * self-heals an already-bricked browser on its next sign-in.
22	 */
23	
24	/** Better Auth's session cookie name, before the `__Secure-` prefix. */
25	export const SESSION_COOKIE_BASENAME = "better-auth.session_token";
26	
27	/**
28	 * Better Auth adds the `__Secure-` prefix whenever it issues secure cookies
29	 * (`useSecureCookies` in auth/index.tsx: NODE_ENV production, or an https
30	 * configured public origin). Derive the name from the resolved public origin —
31	 * TLS is often terminated by a reverse proxy, so the bind speaking plain HTTP
32	 * says nothing about the name the browser actually holds.
33	 */
34	export function sessionCookieName(isHttps: boolean): string {
35		return isHttps ? `__Secure-${SESSION_COOKIE_BASENAME}` : SESSION_COOKIE_BASENAME;
36	}
37	
38	/**
39	 * Count how many times `name` appears in a `Cookie` request header.
40	 *
41	 * More than one is the brick signature: the request carries the same cookie at
42	 * two scopes and the loser is invisible to every log we keep. Matching is on
43	 * the exact name before `=`, so neither a `<name>_other` cookie nor a
44	 * `__Secure-<name>` cookie is mistaken for `<name>`.
45	 */
46	export function countNamedCookies(
47		cookieHeader: string | null | undefined,
48		name: string,
49	): number {
50		if (!cookieHeader) return 0;
51		let count = 0;
52		for (const part of cookieHeader.split(";")) {
53			const eq = part.indexOf("=");
54			if (eq === -1) continue;
55			if (part.slice(0, eq).trim() === name) count += 1;
56		}
57		return count;
58	}
59	
60	/**
61	 * A `Set-Cookie` value that deletes the HOST-ONLY cookie called `name`.
62	 *
63	 * Deliberately carries no `Domain` attribute: cookie deletion matches on
64	 * (name, domain, path), so omitting Domain targets the host-only twin and
65	 * leaves the domain-scoped cookie — the one we actually want the browser to
66	 * keep — untouched. `Secure` is mandatory rather than cosmetic: a browser
67	 * rejects any `Set-Cookie` for a `__Secure-`-prefixed name that lacks it, so
68	 * without it the deletion would silently no-op.
69	 *
70	 * `path` must mirror the source cookie's own `Path` for the same reason Domain
71	 * is omitted: deletion matches on (name, domain, path), so an expiry at `/`
72	 * cannot delete a twin scoped to `/api`. Defaults to `/` — the scope Better
73	 * Auth issues today — but is passed through rather than assumed.
74	 */
75	export function hostOnlyExpiry(name: string, secure: boolean, path = "/"): string {
76		const parts = [`${name}=`, `Path=${path}`, "Max-Age=0", "HttpOnly", "SameSite=Lax"];
77		if (secure) parts.push("Secure");
78		return parts.join("; ");
79	}
80	
81	/**
82	 * Read the `Path` attribute off a `Set-Cookie`, defaulting to `/`.
83	 *
84	 * A cookie sent with no `Path` defaults to the request's directory, which we
85	 * cannot see from here; `/` is the only safe assumption and is what every
86	 * cookie this module converges actually carries.
87	 */
88	function setCookiePath(setCookie: string): string {
89		const match = /;\s*Path=([^;]*)/i.exec(setCookie);
90		const path = match?.[1]?.trim();
91		return path ? path : "/";
92	}
93	
94	/**
95	 * Given the `Set-Cookie` headers a response is about to send, append a
96	 * host-only expiry for every cookie it sets with a `Domain` attribute.
97	 *
98	 * Deletions are converged too, not skipped. Better Auth's sign-out deletes only
99	 * the Domain-scoped cookie, and deletion matches on (name, domain, path), so a
100	 * host-only twin outlives sign-out. Whether that leaves a LIVE session depends
101	 * on which twin the browser happened to send first — the ordering we do not
102	 * control — so sign-out could silently leave the user authenticated. Expiring
103	 * the twin alongside the deletion closes that without cost: an expiry for a
104	 * cookie the browser does not hold is a no-op.
105	 *
106	 * No-ops when no zone is configured: in local dev the host-only cookie IS the
107	 * real session cookie, and expiring it would log the developer out on sign-in.
108	 */
109	export function convergeSetCookieScope(
110		setCookies: string[],
111		opts: { cookieDomain?: string; isHttps: boolean },
112	): string[] {
113		if (!opts.cookieDomain) return setCookies;
114	
115		const out = [...setCookies];
116		const expired = new Set<string>();
117		for (const setCookie of setCookies) {
118			const eq = setCookie.indexOf("=");
119			if (eq === -1) continue;
120			const name = setCookie.slice(0, eq).trim();
121			if (!name || expired.has(name)) continue;
122			// Only a domain-scoped Set-Cookie can be shadowed by a host-only twin.
123			if (!/;\s*Domain=/i.test(setCookie)) continue;
124			if (/;\s*Max-Age=0\b/i.test(setCookie)) continue;
125			expired.add(name);
126			// Mirror the source cookie's Secure, not just our own https detection:
127			// Better Auth decides `useSecureCookies` from NODE_ENV/configured origin,
128			// not from this request's forwarded proto. If it issued a `__Secure-`
129			// cookie, an expiry without Secure is silently rejected — the exact
130			// no-op this module exists to prevent.
131			const secure = opts.isHttps || /;\s*Secure\s*(;|$)/i.test(setCookie);
132			out.push(hostOnlyExpiry(name, secure, setCookiePath(setCookie)));
133		}
134		return out;
135	}
136	
137	/**
138	 * Rewrite a Response's `Set-Cookie` headers in place so every domain-scoped
139	 * auth cookie it sets also expires its host-only twin.
140	 *
141	 * Applied at the `/api/auth/*` chokepoint, this covers every sign-in method at
142	 * once — Google, Slack, magic link, credential, passkey — plus the `state` and
143	 * `pkce_code_verifier` cookies, where a shadowed value breaks the OAuth
144	 * callback rather than the session.
145	 */
146	export function convergeResponseCookieScope(
147		response: Response,
148		opts: { cookieDomain?: string; isHttps: boolean },
149	): Response {
150		if (!opts.cookieDomain) return response;
151		const existing = response.headers.getSetCookie();
152		if (existing.length === 0) return response;
153	
154		const converged = convergeSetCookieScope(existing, opts);
155		if (converged.length === existing.length) return response;
156	
157		response.headers.delete("set-cookie");
158		for (const value of converged) response.headers.append("set-cookie", value);
159		return response;
160	}

