try {
  const cookieHeader = c.req.header('Cookie') || '';
  const candidates = sessionCookieCandidates(cookieHeader);
  // The ordinary jar holds one session cookie, and its value is the cache key.
  // With a duplicate the key is ambiguous, so there is nothing safe to look up.
  const sessionCacheKey = candidates.length === 1 ? candidates[0] : null;

  let session: { user: any; session: any } | null = null;
  let cacheHit = false;
  if (sessionCacheKey) {
    const cached = sessionCache.get(sessionCacheKey);
    if (cached !== undefined) {
      session = cached;
      cacheHit = true;
    }
  }
  if (!cacheHit) {
    const auth = await createAuth(c.env);
    if (candidates.length > 1) {
      // Ambiguous jar: resolve it ourselves instead of letting position
      // decide. Handing the raw header to Better Auth would resolve
      // whichever cookie came FIRST — an ordering set by the browser's
      // creation timestamps, not by us — so a stale twin outranks the real
      // session and no later sign-in can ever win. Ask about each candidate
      // in isolation and take the one that is actually live.
      for (const candidate of candidates) {
        const headers = new Headers(c.req.raw.headers);
        headers.set('cookie', `${SESSION_COOKIE_NAME}=${candidate}`);
        const resolved = await auth.api.getSession({ headers });
        if (resolved?.user && resolved.session) {
          session = resolved;
          // Cache under the winner, so once the jar collapses back to one
          // cookie the ordinary path hits.
          sessionCache.set(candidate, resolved);
          break;
        }
      }
    } else {
      session = await auth.api.getSession({ headers: c.req.raw.headers });
      // Only cache valid sessions. Caching `null` would let an explicitly
      // revoked or expired session continue to resolve to "no auth" for
      // the cache TTL (30s) instead of returning the upstream's fresh
      // verdict — fine on its own, but it also masks the inverse case
      // where the user just logged in: the prior `null` answer keeps
      // them logged out until the entry expires.
      if (sessionCacheKey && session?.user && session.session) {
        sessionCache.set(sessionCacheKey, session);
      }
    }
  }

