 */
const UNSCOPED_PATH_PREFIXES = ['/mcp/', '/api/me/', '/api/workers/'];

export function invalidateMembershipRoleCache(
  organizationId: string,
  userId: string | null | undefined
): void {
  if (!userId) return;
  memberRoleCache.delete(`${organizationId}:${userId}`);
}

