const UNSCOPED_PATH_PREFIXES = ['/mcp/', '/api/me/', '/api/workers/'];

/**
 * Better Auth's session cookie, unprefixed and with the `__Secure-` prefix it
 * adds when issuing secure cookies. Both can be present at once.
 */
const SESSION_COOKIE_NAME = 'better-auth.session_token';
const SESSION_COOKIE_NAMES = [SESSION_COOKIE_NAME, `__Secure-${SESSION_COOKIE_NAME}`];

/**
 * Every session-cookie value in a `Cookie` header, in the order sent.
 *
 * Normally there is exactly one. But the same cookie name can exist at two
 * scopes at once — host-only (`app.lobu.ai`) and domain-scoped
 * (`Domain=.lobu.ai`) — and the browser sends BOTH in one header. Resolution is
 * then decided purely by position, and the position is not ours to choose:
 *
 *   RFC 6265 §5.4  browser sends equal-path cookies oldest-first
 *   better-call    parseCookies keeps the FIRST occurrence (`if (!cookies.has(key))`)
 *   better-auth    getSignedCookie reads that one and stops
 *
 * So a stale twin that happens to be older silently outranks the real session,
 * and signing in again cannot help — a fresh cookie is always the NEWER one.
 * Returning every candidate lets the caller resolve the jar on merit instead.
 *
 * Values are returned raw; only the caller's `getSession` can say which verify.
 */
function sessionCookieCandidates(cookieHeader: string): string[] {
  if (!cookieHeader) return [];
  const values: string[] = [];
  for (const part of cookieHeader.split(';')) {
    const eq = part.indexOf('=');
    if (eq === -1) continue;
    // Exact name match, so `<name>_other` is never mistaken for `<name>`.
    if (!SESSION_COOKIE_NAMES.includes(part.slice(0, eq).trim())) continue;
    const value = part.slice(eq + 1).trim();
    if (value) values.push(value);
  }
  return values;
}

