113	    const session = await auth.api.getSession({ headers: single });
114	    if (isLive(session)) return session;
115	  }
116	  // Every candidate was dead. Resolving on merit must not become "authenticate
117	  // on anything" — an ambiguous jar with no live token is still no session.
118	  return null as SessionOf<A>;
119	}

