29	 * prefix only when issuing secure cookies, and a jar can outlive that switch.
30	 */
31	const SESSION_COOKIE_NAMES = [sessionCookieName(false), sessionCookieName(true)];
32	
33	/**
34	 * How many candidates one request may cost us.
35	 *
