37	 * unbounded loop turns one unauthenticated request into ~100 of them. A real
38	 * jar holds a twin or two (host-only, domain, occasionally a parent domain, and
39	 * at most one leftover of the other spelling), so this is far above anything a
40	 * browser produces and still bounds the cost.
41	 */
42	const MAX_CANDIDATES = 8;
43	
44	/** One session cookie as the jar carries it: its exact name and raw value. */
45	type SessionCookieCandidate = { name: string; value: string };
