69	  cookieHeader: string | null | undefined
70	): SessionCookieCandidate[] {
71	  if (!cookieHeader) return [];
72	  const candidates: SessionCookieCandidate[] = [];
73	  for (const part of cookieHeader.split(';')) {
74	    const eq = part.indexOf('=');
75	    if (eq === -1) continue;
76	    const name = part.slice(0, eq).trim();
77	    if (!SESSION_COOKIE_NAMES.includes(name)) continue;
78	    const value = part.slice(eq + 1).trim();
