93	 * `getSession` behaves: `better-auth.dont_remember` gates session-expiry
94	 * refresh, and `better-auth.session_data` is its cookie cache. Dropping the
95	 * whole header would give a duplicated jar different refresh semantics from a
96	 * clean one — a difference that has nothing to do with which twin is live.
97	 */
98	function nonSessionCookies(cookieHeader: string | null): string[] {
99	  if (!cookieHeader) return [];
100	  const kept: string[] = [];
101	  for (const part of cookieHeader.split(';')) {
102	    const pair = part.trim();
103	    if (!pair) continue;
104	    const eq = pair.indexOf('=');
105	    if (eq === -1) continue;
106	    if (SESSION_COOKIE_NAMES.includes(pair.slice(0, eq).trim())) continue;
107	    kept.push(pair);
108	  }
109	  return kept;
110	}
